import django
from django.conf import settings
settings.configure(INSTALLED_APPS=['django.contrib.contenttypes','django.contrib.auth'], DATABASES={'default':{'ENGINE':'django.db.backends.sqlite3','NAME':':memory:'}})
django.setup()
from django.db import models

# 1. Explicit override is retained.
class FooBar(models.Model):
    foo_bar = models.CharField("foo", choices=[(1, 'foo'), (2, 'bar')], max_length=1)
    def __str__(self):
        return self.get_foo_bar_display()
    def get_foo_bar_display(self):
        return "something"
    class Meta:
        app_label = 'auth'

assert FooBar(foo_bar=1).get_foo_bar_display() == "something"
assert str(FooBar(foo_bar=1)) == "something"

# 2. No override -> generated method still works.
class Plain(models.Model):
    kind = models.CharField(max_length=1, choices=[(1, 'foo'), (2, 'bar')])
    class Meta:
        app_label = 'auth'
assert Plain(kind=1).get_kind_display() == 'foo'
assert Plain(kind=2).get_kind_display() == 'bar'

# 3. Abstract parent field w/ choices: concrete child gets generated method.
class AbstractBase(models.Model):
    kind = models.CharField(max_length=1, choices=[(1, 'foo')])
    class Meta:
        abstract = True
        app_label = 'auth'
class Child(AbstractBase):
    class Meta:
        app_label = 'auth'
assert Child(kind=1).get_kind_display() == 'foo'

# 4. Child overriding inherited choices must get a fresh generated method.
class BaseConcrete(models.Model):
    kind = models.CharField(max_length=1, choices=[(1, 'foo')])
    class Meta:
        app_label = 'auth'
class OverrideChoices(BaseConcrete):
    kind = models.CharField(max_length=1, choices=[(9, 'nine')])
    class Meta:
        app_label = 'auth'
assert OverrideChoices(kind=9).get_kind_display() == 'nine'

# 5. Child explicitly overriding an inherited generated method is retained.
class OverrideBoth(BaseConcrete):
    def get_kind_display(self):
        return 'override'
    class Meta:
        app_label = 'auth'
assert OverrideBoth(kind=1).get_kind_display() == 'override'

print("ALL EDGE CASES OK")
